function load(){try{const x=JSON.parse(localStorage.getItem(KEY));if(x&&Array.isArray(x.plants)&&Array.isArray(x.tasks)&&Array.isArray(x.done)&&Array.isArray(x.zoneNames))return x;}catch(e){}return structuredClone(defaults)}
let state=load(),view='home',editing=null,month=new Date().getMonth(),year=new Date().getFullYear();
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=()=>crypto.randomUUID?crypto.randomUUID():String(Date.now())+Math.random();
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true}catch(e){alert('Sauvegarde impossible : stockage local indisponible ou plein. Exportez vos données.');return false}}
function go(v){view=v;editing=null;render();window.scrollTo({top:0,behavior:'smooth'})}
